# Generated by Cursor (plan item 2: title abbreviations)
"""Scan for title abbreviations (Mr., Dr., Mrs., Jr., etc.); emit (rule_id, start, span, path_str)."""

import re

# Title subset: must be followed by space, end, comma, or paren. Plan item 2.
TITLE_ABBREV_RE = re.compile(
    r"\b(Mr|Mrs|Ms|Dr|Jr|Sr|Gen|Gov|Hon|Prof|Rev|Sec|Rep|Sen)\.(?=\s|$|[,\)])"
)


def scan_turn_title_abbreviation(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """Emit (title_abbreviation, start_index, span, path_str) for each title abbreviation."""
    result: list[tuple[str, int, str, str]] = []
    for m in TITLE_ABBREV_RE.finditer(text):
        result.append(("title_abbreviation", m.start(), m.group(0), path_str))
    return result
